( 
    TENANT_ID
    , MODULE_ID
     , PURCHASED_AT 
)
VALUES  
( 
    #{tenantId}
    , #{moduleId}
     , #{purchasedAt} 

)

mapper.update:


  UPDATE TENANT_MODULE    /* QueryID : com.demo.proworks.tenantModule.updateTenantModule */      
	  SET  
          TENANT_ID    = #{tenantId}   
   ,  MODULE_ID    = #{moduleId}   

       , PURCHASED_AT = #{purchasedAt} 

  WHERE   
          TENANT_ID    = #{tenantId}   
   AND MODULE_ID    = #{moduleId}

mapper.delete:


DELETE FROM TENANT_MODULE   /* QueryID : com.demo.proworks.tenantModule.deleteTenantModule */ 
WHERE   
        TENANT_ID    = #{tenantId}   
 AND MODULE_ID    = #{moduleId}

mapper.select:

SELECT     /* QueryID : com.demo.proworks.tenantModule.selectTenantModule */
    TENANT_ID as tenantId, MODULE_ID as moduleId, PURCHASED_AT as purchasedAt
FROM TENANT_MODULE 
WHERE 
        TENANT_ID    = #{tenantId}   
 AND MODULE_ID    = #{moduleId}

SELECT /* QueryID : com.demo.proworks.tenantModule.selectListTenantModule */ TENANT_ID as tenantId, MODULE_ID as moduleId, PURCHASED_AT as purchasedAt FROM ( SELECT S.*, CEIL( (@ROWNUM:=@ROWNUM+1) / #{pageSize} ) AS PAGE FROM ( SELECT * FROM TENANT_MODULE WHERE 1=1
AND TENANT_ID like '%${scTenantId}%'
AND MODULE_ID like '%${scModuleId}%'
AND PURCHASED_AT like '%${scPurchasedAt}%'
) S, (SELECT @ROWNUM := 0) TMP ) A WHERE PAGE = #{pageIndex}
